{
  "devices": ["$$A$$", "$$B$$", "$$C$$", "$$D$$"],
  "products": ["$$P_1$$"],
  "planning_horizon": "$$\mathcal{T}$$",
  "demand": {
    "$$P_1$$": "$$2000$$"
  },
  "setup_cost": {
    "$$A$$": "$$1000$$",
    "$$B$$": "$$920$$",
    "$$C$$": "$$800$$",
    "$$D$$": "$$700$$"
  },
  "unit_production_cost": {
    "$$A$$": {
      "$$P_1$$": "$$20$$"
    },
    "$$B$$": {
      "$$P_1$$": "$$24$$"
    },
    "$$C$$": {
      "$$P_1$$": "$$16$$"
    },
